DO $$ DECLARE d text; target text := 'IF lower(btrim(p->>''category''))=''marmitas'' AND (now() AT TIME ZONE ''America/Bahia'')::time >= time ''14:00'' THEN RAISE EXCEPTION ''Marmitas indisponíveis após 14:00''; END IF;'; replacement text := 'IF lower(btrim(p->>''category''))=''marmitas'' AND ((now() AT TIME ZONE ''America/Bahia'')::time >= time ''14:00'' OR (now() AT TIME ZONE ''America/Bahia'')::time < time ''09:00'') THEN RAISE EXCEPTION ''Marmitas disponíveis das 09:00 às 14:00''; END IF;'; BEGIN d:=pg_get_functiondef('public.catalog_place_order(uuid,jsonb)'::regprocedure); IF position(target IN d)=0 THEN RAISE EXCEPTION 'Catalog marmita schedule insertion point missing'; END IF; EXECUTE replace(d,target,replacement); END $$;